    try {
        // WebSquare에서는 $p.parent()를 사용하여 부모 프레임에 접근
        var parentFrame = $p.parent();

        if (parentFrame && parentFrame.scwin && parentFrame.scwin.changeMenu) {
            console.log("부모 changeMenu 함수 호출: project1 ($p.parent)");
            parentFrame.scwin.changeMenu("project1");
        } else if (parent && parent.scwin && parent.scwin.changeMenu) {
            console.log("부모 changeMenu 함수 호출: project1 (parent)");
            parent.scwin.changeMenu("project1");
        } else if (window.parent && window.parent.scwin && window.parent.scwin.changeMenu) {
            console.log("부모 changeMenu 함수 호출: project1 (window.parent)");
            window.parent.scwin.changeMenu("project1");
